def transform(grid):
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row),
                     key=lambda v: sum(row.count(v) for row in grid))
    obj = next(v for v in set(v for row in grid for v in row) if v != background)
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] == obj and row[c + 2] == obj and row[c + 1] == background:
                out[r][c + 1] = 2
    return out
